#include "ksSerialQueueTask.h"
#include <stdexcept>
#include <iostream>
#include <vector>
#include <utility>
int main(){using T=ks::SerialQueueTask;using S=T::Stage;using W=T::Write;unsigned cases=0;auto verify=[&](unsigned kind,unsigned producer,unsigned consumer,unsigned status,unsigned data){T t(static_cast<T::Kind>(kind));std::vector<std::pair<W,unsigned>>writes;std::vector<T::Read>reads;unsigned used=0;auto clock=[&]{return t.dataAddress()>=0xfffd10?1u:3u;};while(t.stage()!=S::Complete){auto cost=t.nextClocks(clock);if(t.advanceBefore(cost-1,[](T::Read){return 0;},[](W,uint16_t){},clock))throw std::runtime_error("early");used+=t.advanceBefore(cost,[&](T::Read r){reads.push_back(r);return r==T::Read::Status?status:r==T::Read::Consumer?consumer:r==T::Read::Producer?producer:data;},[&](W w,uint16_t v){writes.emplace_back(w,v);},clock);}std::vector<std::pair<W,unsigned>>expected;std::vector<T::Read>er;if(kind==1){expected.emplace_back(W::Status,0);er={T::Read::Status,T::Read::Consumer,T::Read::Producer};if(producer!=consumer){expected.emplace_back(W::Consumer,(consumer+1)&255);er.push_back(T::Read::Data);}unsigned result=producer==consumer?status<<8:(status|1)<<8|data;if(t.result()!=result||t.dataAddress()!=((0xffec68+consumer)&0xffffff))throw std::runtime_error("pop/result/address");unsigned clocks=191+(producer!=consumer?45+clock():0);if(used!=clocks)throw std::runtime_error("pop clocks");}else{expected={{W::Producer,0},{W::Consumer,0}};if(kind==0)expected.emplace_back(W::Status,0);if(used!=(kind==0?118u:106u))throw std::runtime_error("reset clocks");}if(writes!=expected||reads!=er)throw std::runtime_error("queue ordered accesses");++cases;};for(unsigned producer=0;producer<256;++producer)for(unsigned consumer=0;consumer<256;++consumer)verify(1,producer,consumer,(producer+consumer)&255,producer^consumer);for(unsigned kind=0;kind<3;++kind)for(unsigned status=0;status<256;++status)for(unsigned data=0;data<256;++data)verify(kind,0,255,status,data);for(unsigned consumer=0;consumer<65536;++consumer)verify(1,consumer^1,consumer,255,(consumer*149)&255);std::cout<<"PASS: "<<cases<<" pure serial-queue properties\n";}
